TLM.f("Tempora/Pent19-5",{"officium":"Feria Sexta infra Hebdomadam XIX post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent19-0","from":{"Introitus":"Tempora/Pent19-0","Oratio":"Tempora/Pent19-0","Lectio":"Tempora/Pent19-0","Graduale":"Tempora/Pent19-0","Evangelium":"Tempora/Pent19-0","Offertorium":"Tempora/Pent19-0","Secreta":"Tempora/Pent19-0","Communio":"Tempora/Pent19-0","Postcommunio":"Tempora/Pent19-0"},"sections":{"Introitus":[{"k":"text","la":"Salus pópuli ego sum, dicit Dóminus: de quacúmque tribulatióne clamáverint ad me, exáudiam eos: et ero illórum Dóminus in perpétuum."},{"k":"ref","la":"Ps 77:1"},{"k":"text","la":"Attendite, pópule meus, legem meam: inclináte aurem vestram in verba oris mei."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salus pópuli ego sum, dicit Dóminus: de quacúmque tribulatióne clamáverint ad me, exáudiam eos: et ero illórum Dóminus in perpétuum"}],"Oratio":[{"k":"text","la":"Omnípotens et miséricors Deus, univérsa nobis adversántia propitiátus exclúde: ut mente et córpore páriter expedíti, quæ tua sunt, líberis méntibus exsequámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios"},{"k":"ref","la":"Ephes 4:23-28"},{"k":"text","la":"Fratres: Renovámini spíritu mentis vestræ, et indúite novum hóminem, qui secúndum Deum creátus est in justítia et sanctitáte veritátis. Propter quod deponéntes mendácium, loquímini veritátem unusquísque cum próximo suo: quóniam sumus ínvicem membra. Irascímini, et nolíte peccáre: sol non occídat super iracúndiam vestram. Nolíte locum dare diábolo: qui furabátur, jam non furétur; magis autem labóret, operándo mánibus suis, quod bonum est, ut hábeat, unde tríbuat necessitátem patiénti."}],"Graduale":[{"k":"ref","la":"Ps 140:2"},{"k":"text","la":"Dirigátur orátio mea, sicut incénsum in conspéctu tuo, Dómine."},{"k":"text","la":"Elevatio mánuum meárum sacrifícium vespertínum. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 104:1"},{"k":"text","la":"Confitémini Dómino, et invocáte nomen ejus: annuntiáte inter gentes ópera ejus. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 22:1-14"},{"k":"text","la":"In illo témpore: Loquebátur Jesus princípibus sacerdótum et pharisǽis in parábolis, dicens: Símile factum est regnum cœlórum hómini regi, qui fecit núptias fílio suo. Et misit servos suos vocáre invitátos ad nuptias, et nolébant veníre. Iterum misit álios servos, dicens: Dícite invitátis: Ecce, prándium meum parávi, tauri mei et altília occísa sunt, et ómnia paráta: veníte ad núptias. Illi autem neglexérunt: et abiérunt, álius in villam suam, álius vero ad negotiatiónem suam: réliqui vero tenuérunt servos ejus, et contuméliis afféctos occidérunt. Rex autem cum audísset, iratus est: et, missis exercítibus suis, pérdidit homicídas illos et civitátem illórum succéndit. Tunc ait servis suis: Núptiæ quidem parátæ sunt, sed, qui invitáti erant, non fuérunt digni. Ite ergo ad exitus viárum et, quoscúmque invenéritis, vocáte ad núptias. Et egréssi servi ejus in vias, congregavérunt omnes, quos invenérunt, malos et bonos: et implétæ sunt núptiæ discumbéntium. Intrávit autem rex, ut vidéret discumbéntes, et vidit ibi hóminem non vestítum veste nuptiáli. Et ait illi: Amíce, quómodo huc intrásti non habens vestem nuptiálem? At ille obmútuit. Tunc dixit rex minístris: Ligátis mánibus et pédibus ejus, míttite eum in ténebras exterióres: ibi erit fletus et stridor déntium. Multi enim sunt vocáti, pauci vero elécti."}],"Offertorium":[{"k":"ref","la":"Ps 137:7"},{"k":"text","la":"Si ambulávero in médio tribulatiónis, vivificábis me, Dómine: et super iram inimicórum meórum exténdes manum tuam, et salvum me fáciet déxtera tua."}],"Secreta":[{"k":"text","la":"Hæc múnera, quǽsumus, Dómine, quæ óculis tuæ majestátis offérimus, salutária nobis esse concéde."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:4-5"},{"k":"text","la":"Tu mandásti mandáta tua custodíri nimis: útinam dirigántur viæ meæ, ad custodiéndas justificatiónes tuas."}],"Postcommunio":[{"k":"text","la":"Tua nos, Dómine, medicinális operátio, et a nostris perversitátibus cleménter expédiat, et tuis semper fáciat inhærére mandátis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"541acd807df0ea9d":{"t":"Ja sam spasenje naroda, kaže Gospodin. Ja ću ih uslišiti, iz kakve god nevolje zavapili k meni, i bit ću njihov Gospodin do vijeka. (Ps 77.1) Čuj, puče moj, zakon moj, prigni uho svoje k riječima usta mojih.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nJa sam spasenje naroda, kaže Gospodin. Ja ću ih uslišiti, iz kakve god nevolje zavapili k meni, i bit ću njihov Gospodin do vijeka.","kn":"Ja sam spasenje puka, veli Gospodin, iz koje god .nevolje poviču k meni, uslišati ću ih i bit ćii im Gospodin do vijeka. (Ps. 77. 1). Guj, narode moj, zakon moj, prigni uho svoje k-, -riječima usta mojih. 'Slava Ocu... Ja sam... slava.","knRef":"Kniewald 1942, str. 420–421 (snimka 211) (OCR)"},"e927f61b00b4b3ee":{"t":"<i>Pomolimo se</i>.\nSvemogući i milosrdni Bože, udalji milostivo od nas sve što nam priječi, da bez zapreke u duši i tijelu slobodno izvršujemo tvoju službu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući’ i milosrdni Bože, svekolike nam protivnosti umoljen cdaleći, da u duši i tijelu jednako olakšarii, što je Tvoje slobodnim dušama izvršujemo, po G. n.","knRef":"Kniewald 1942, str. 420–421 (snimka 211) (OCR)"},"29b5866fc9afdd3b":{"t":"Ef 13, 11-14\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo: obnovite se u srcu i umu i obucite novoga čovjeka stvorena na Božju sliku u stvarnoj pravdi i svetosti. Zato, odbacite laž i govorite istinu svaki sa svojim bližnjim, jer smo udovi jedan drugomu. Srdite se, ali ne grješno! Neka sunce ne zađe nad vašom srdžbom. Ne dajte mjesta đavolu! Tko je krao, neka više ne krade. Mjesto toga neka pošteno radi svojim rukama, da bi imao od čega dati potrebnima.","kn":"Čitanje poslanice bi. Pavla apostola Efežanima (4 23-28), Braćo! i Obnouite se duhom svpje pameti, i obucite novoga čovjeka, koji je stvoren po Bogu u pravdi ,i iskrenoj svetosti. Zato -odbacite laz i govorite - istinu svaki svomu bližnj emu, jer smo udovi jedan drugomu. - Srdite se, ali, nemojte griješiti; neka sunce. ,ne zađe nad vašom srdzbo-m. Ne dajte mjesta đavlu! Tko je krao, neka više ne krade, nego neka se radije trudi, da radi. svojim • rukama, što je dobro, da ima, otkuda će dati i potrebnomu. .","knRef":"Kniewald 1942, str. 420–421 (snimka 211) (OCR)"},"7d9b27c9821beb70":{"t":"Ps 140, 2\nNeka se vine molitva moja k tebi kao tamjan, dizanje ruku mojih kao večernja žrtva.\n\nPs 104, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nHvalite Gospodina i prizivajte ime njegovo, navješćujte među narodima djela njegova. <i>Aleluja</i>.","kn":"<i>Aleluja</i>, <i>aleluja</i>.\n(Ps. 140, 2). Vinula se preda Te molitva moja. Gospodine, kao kad pred licem Tvojim, dizanje ruku mojih kao žrtva večernja. Alelnia, aleluija. (Ps. 104, 1) Slavite Gospodina I zazivajte ime njegovo; oglašujte među neznabošcima djela njegova, Aleluja.","knRef":"Kniewald 1942, str. 422–423 (snimka 212) (OCR)"},"2c1e7be4baae2775":{"t":"Mt 22, 1-14\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme govoraše Isus svećeničkim prvacima i farizejima u poredbama: Nebesko je kraljevstvo slično vladaru koji priredi svadbu svojemu sinu, pa posla svoje sluge da pozovu uzvanike na svadbu. Ali uzvanici nisu htjeli doći. Tada posla druge sluge i reče im: Kažite uzvanicima: Pripravio sam gozbu, moji su junci i utovljenici zaklani, i sve je pri pravljeno; dođite na svadbu. Ali oni nisu marili za to, nego pođoše netko u svoje polje, netko u svoju trgovinu, a ostali uhvatiše njegove sluge pa ih pogrdiše i ubiše. Kad to ču vladar, rasrdi se. On pošalje svoju vojsku; te pogubi one ubojice, a grad njihov spali. Tada reče svojim slugama: Gozba je doista pripremljena; ali pozvani nisu bili dostojni. Pođite zato na raskršća putova i pozovite na svadbu koga god nađete. Njegove sluge izađoše na putove te dovedoše sve koje nađoše zle i dobre. I svadbena se dvorana napuni gostiju. Kad uđe vladar da vidi goste, ugleda ondje jednoga koji nije bio obučen u svadbeno ruho. Vladar ga upita: Prijatelju, kako si amo ušao bez svadbenoga ruha? A on ušuti. Tada vladar zapovjedi slugama: Svežite mu ruke i noge i bacite ga van u tamu. Ondje će biti plač i škrgut zuba. Mnogo je zvanih, ali je malo izabranih.","kn":"t Slijedi sveto evanđelje po Mateju (22, 1-4). U ono vrijertie govorio je Isus velikim svećenicima u prispodabamai: Kraljevstvo je nebesko kao kralj, koji je priredio svojemu sinu svadbu. I posla svoje sluge, da pozovu uzvanike na svadbu. Ovi nijesu htjeli doći. Opet posla druge sluge i reče dm: Kažite uizvanicima: Prip.ravio sam svoj objed, moji su junci i branjenici poklani i sve je gotovo. Dođite na svadbu ! Ali oni ne mareći odu, netko u svoj zaselak, netko u svoju trgovinu. Ostali uhvate njegove sluge, pogrde ih i ubiju. Kad to ču kralj, rasrdi se, posla svoju vojsku, pogubi one ubojice, a njihov grad zapali. Tada reče svojim slugama: Svadba je doduše pripravljena, ali uzvanici nijesu bili dostojni. Idite, dakle, na raskršća, i kojegod nađete, pozovite na svadbu. Kad su njegovi sluge izašli na puteve, saberu sve, zle i dobre, koje' .su našli i svadbena se dvorana napuni gostiju. Ali kad uđe kralj da vidi goste, ugleda ondje čovjeka, koji nije bio odjeven u svadbeno ruho. I upita ga: Prijatelju, kako si ušao ovamo bez svadbenoga ruha? A on zanijemi. Kralj tada zapovjedi slugama: Svežite mu ruke i noge, bacite ga van u tamu!. Ondje će biti plač 1 škripa zubima. Jer je mnogo zvanih,, a malo izabranih.","knRef":"Kniewald 1942, str. 422–423 (snimka 212) (OCR)"},"59143326cd9fbc72":{"t":"Ps 137, 7\nAko se nađem usred nevolje, čuvaš me živa. Protiv srdžbe neprijatelja mojih pružaš svoju ruku, spašava me desnica tvoja.","kn":"(Ps. 137, 7). Kad sam posred nevolje. Ti me. Gospodine,, oživljuješ; pružaš ruku protiv srdžbe neprijatelja mojih i spasava me desnica Tvoja. . .","knRef":"Kniewald 1942, str. 422–423 (snimka 212) (OCR)"},"5c359c14ab0a3276":{"t":"Podaj, molimo, Gospodine, da nam budu na spas ovi darovi što ih prinosimo očima tvoga veličanstva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da nam ovi darovi, sto ih prinosimo očima Tvojega veličanstva, budu na spasenje, po G. n.","knRef":"Kniewald 1942, str. 422–423 (snimka 212) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"30c37247f261fbf5":{"t":"Ps 118, 4-5\nTi si zapovjedio da se tvoje zapovijedi dobro čuvaju. O da bi moji putovi bili upravljeni da čuvam naloge tvoje!","kn":"(Ps. 118, 4, 5). Ti si zapovjedio, da se zapovijedi Tvoje održavaju; o, da bi se putovi moji upravili putem obdržavanja Tvoje pravde!","knRef":"Kniewald 1942, str. 162–163 (snimka 82) (OCR)"},"0666a8c364da6524":{"t":"<i>Pomolimo se</i>.\nTvoje spasonosno djelovanje, Gospodine, neka nas milostivo oslobodi od naših opačina i dade da uvijek budemo privrženi tvojim zapovijedima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Tvoje nas. Gospodine, ljekovito djelovanje i od naših opačina milostivo oslobodilo i Tvojim vazda priljubilo nalozima, po .G. n.","knRef":"Kniewald 1942, str. 422–423 (snimka 212) (OCR)"}}});
